nativeSource:
{
  --lini-font-family: Arial;
  .lini-block { font-family: Arial; }
  .lini-caption { translate: 0 -30; font-scale: 14 16; }
  .e1 { stroke: --teal-deep; }
  .e2 { stroke: --teal-deep; }
  .e3 { stroke: --teal-deep; }
  .e4 { stroke: --teal-deep; }
}
|group#visual| "V5 · When a response is lost" { layout: flow; direction: column; gap: 72; padding: 36; fill: none; stroke: none; stroke-width: 0; } [
  |box#n1| "Client → consumer" { width: 240; } [
    |cell#detail| "Send original token, revision, typed\ninputs and expected versions. Trusted\ncontext supplies actor identity."
  ]
  |box#n2| "Consumer → native store" { width: 240; } [
    |cell#detail| "Commit business changes, verification\nand terminal outcome atomically. Then\nthe acknowledgement is lost."
  ]
  |box#n3| "Response lost · Client\nknowledge · indeterminate" { width: 240; } [
    |cell#detail| "Unknown whether commit occurred.\nTimeout does not prove rollback. Keep\nthe original request; do not mint a\nfresh token."
  ]
  |box#n4| "Client → protected lookup" { width: 240; } [
    |cell#detail| "Current discovery and original-result\nauthorization gate lookup. Return the\nretained original outcome; lookup\nnever executes."
  ]
  |box#n5| "Missing or expired" { width: 240; } [
    |cell#detail| "Missing after uncertainty is not\npermission to reexecute. No-key\nrequests lack keyed recovery\nguarantees."
  ]
  n1 -> n2 "Original request" .e1 { along: 0.35; }
  n2 -> n3 "Acknowledgement lost" .e2 { along: 0.5; }
  n3 -> n4 "Recover with the original token" .e3 { along: 0.65; }
  n4 -> n5 "If missing or expired" .e4 { along: 0.35; }
]
